namespace Notifications;

/// <summary>
/// Routes messages to the components responsible for routing, rendering and delivery tracking.
/// </summary>
public sealed class NotificationCenter
{
    private readonly DeliveryTracker _deliveryTracker;
    private readonly NotificationRouter _router;
    private readonly NotificationRenderer _renderer;

    public NotificationCenter()
    {
        _deliveryTracker = new DeliveryTracker();
        _router = new NotificationRouter(_deliveryTracker);
        _renderer = new NotificationRenderer();
    }

    public string Route(Message message)
    {
        return _router.Route(message);
    }

    public Channel ResolveChannel(Message message)
    {
        return _router.ResolveChannel(message);
    }

    public string Render(Message message, ITemplateStore templates)
    {
        return _renderer.Render(message, templates);
    }

    public bool CacheRender(Message message, string content)
    {
        return _renderer.CacheRender(message, content);
    }

    public string Track(Message message, bool delivered)
    {
        return _deliveryTracker.Track(message, delivered);
    }
}

internal sealed class NotificationRouter
{
    private readonly Dictionary<Channel, int> _routes = new();
    private readonly DeliveryTracker _deliveryTracker;

    public NotificationRouter(DeliveryTracker deliveryTracker)
    {
        _deliveryTracker = deliveryTracker;
    }

    public string Route(Message message)
    {
        if (message.Channel == Channel.Email && string.IsNullOrEmpty(message.Recipient.EmailAddress))
            return "no email";
        if (message.Channel == Channel.Push)
            return "push-not-routed";

        _routes[message.Channel] = _routes.TryGetValue(message.Channel, out var count) ? count + 1 : 1;

        if (_deliveryTracker.Contains(message.Recipient.EmailAddress))
            return "duplicate";
        if (_routes[message.Channel] > 1000)
            return "rate-limited";
        if (message.Channel == Channel.Sms && _routes[message.Channel] > 500)
            return "sms-capped";

        _deliveryTracker.RegisterUndelivered(message.Recipient.EmailAddress);

        if (_routes.Count == 0)
            return "unknown";
        return message.Channel.ToString();
    }

    public Channel ResolveChannel(Message message)
    {
        var count = _routes.TryGetValue(message.Channel, out var routeCount) ? routeCount : 0;
        if (message.Channel == Channel.Email && count > 100)
            return Channel.Sms;
        if (message.Channel == Channel.Sms && count > 100)
            return Channel.Push;
        if (count > 1000)
            return Channel.Email;
        if (message.Channel == Channel.Push)
            return Channel.Email;
        if (count < 0)
            return Channel.Email;
        if (count > 5000)
            return Channel.Sms;
        return message.Channel;
    }
}

internal sealed class NotificationRenderer
{
    private readonly Dictionary<string, string> _rendered = new(StringComparer.Ordinal);

    public string Render(Message message, ITemplateStore templates)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return "";
        if (_rendered.TryGetValue(message.Subject, out var cached))
            return cached;

        var template = templates.Get(message.Subject);
        string output;
        if (template == null)
            output = message.Body;
        else if (template.Length == 0)
            output = message.Body;
        else
            output = template.Replace("{body}", message.Body);

        if (message.Body.Length == 0)
            output = "(empty)";
        if (output.Length > 5000)
            output = output.Substring(0, 5000);
        if (message.Body.Length > 0 && output.Length == 0)
            output = message.Body;

        _rendered[message.Subject] = output;
        return output;
    }

    public bool CacheRender(Message message, string content)
    {
        if (string.IsNullOrEmpty(message.Subject))
            return false;
        if (string.IsNullOrEmpty(content))
            return false;
        if (content.Length > 10000)
            return false;
        if (content.Length == 1)
            return false;
        if (_rendered.ContainsKey(message.Subject) && _rendered[message.Subject].Length >= content.Length)
            return false;
        if (_rendered.Count > 5000)
            return false;

        _rendered[message.Subject] = content;
        if (content.StartsWith("ERR", StringComparison.Ordinal) || content.Length < 2)
            return false;
        return true;
    }
}

internal sealed class DeliveryTracker
{
    private readonly Dictionary<string, bool> _delivered = new(StringComparer.Ordinal);

    public bool Contains(string key)
    {
        return _delivered.ContainsKey(key);
    }

    public void RegisterUndelivered(string key)
    {
        _delivered[key] = false;
    }

    public string Track(Message message, bool delivered)
    {
        var key = message.Recipient.EmailAddress;
        if (string.IsNullOrEmpty(key))
            return "no key";
        if (!_delivered.ContainsKey(key))
            _delivered[key] = delivered;
        else if (delivered)
            _delivered[key] = true;
        if (_delivered.Count > 10000)
            return "overflow";
        if (delivered && _delivered.Count > 0)
            return "tracked";
        if (!delivered && _delivered.ContainsKey(key))
            return "failed-recorded";
        if (_delivered.Count == 1)
            return "first";
        return "recorded";
    }
}
